$('hFromComp').onclick=()=>hierarchyFromSVG();$('hImage').onchange=async e=>{const f=e.target.files?.[0];if(!goodFile(f,['image/png','image/jpeg','image/webp'],30))return;try{hImg=await readImage(f);hSource=f.name;state.hierarchy.points=[];state.hierarchy.source=f.name;delete state.hierarchy.handoff;persist();drawHierarchy();$('hImageStatus').textContent=f.name+' · '+hImg.naturalWidth+' × '+hImg.naturalHeight}catch{toast('No se pudo abrir el archivo')}finally{e.target.value=''}};
$('hTarget').onclick=e=>{if(!hImg)return;const r=$('hOriginal').getBoundingClientRect(),x=(e.clientX-r.left)/r.width*100,y=(e.clientY-r.top)/r.height*100;if(x<0||x>100||y<0||y>100)return;if(state.hierarchy.points.length===3)state.hierarchy.points=[];state.hierarchy.points.push({x:Math.round(x*10)/10,y:Math.round(y*10)/10});persist();renderPoints()};
