$('hExportPNG').onclick=()=>{if(!hImg)return toast('Cargá una imagen');const out=document.createElement('canvas');out.width=1600;out.height=1740;const cx=out.getContext('2d');cx.fillStyle='#F3F1EA';cx.fillRect(0,0,1600,1740);cx.fillStyle='#1B2420';cx.font='800 57px Arial';cx.fillText('LECTURA / JERARQUÍA',65,85);cx.font='21px Arial';cx.fillText('LAB/OFICIO · Comparativa de percepción · marcas manuales',65,123);const visuals=[['ORIGINAL','none'],['GRISES','grayscale(1)'],['DESENFOQUE','blur(14px)'],['REDUCIDO','none']];const ar=(hImg.naturalWidth||hImg.width)/(hImg.naturalHeight||hImg.height);visuals.forEach(([name,filter],i)=>{const left=65+(i%2)*752,top=175+Math.floor(i/2)*555;cx.fillStyle='#FFFFFF';cx.fillRect(left,top,714,505);cx.fillStyle='#455149';cx.font='bold 18px Arial';cx.fillText('0'+(i+1)+' / '+name,left+17,top+31);const maxW=i===3?180:680,maxH=i===3?265:435;const w=Math.min(maxW,maxH*ar),h=w/ar,dx=left+(714-w)/2,dy=top+48+(435-h)/2;cx.save();cx.filter=filter;cx.drawImage(hImg,dx,dy,w,h);cx.restore();if(i===0){state.hierarchy.points.forEach((p,j)=>{const xx=dx+w*p.x/100,yy=dy+h*p.y/100;cx.beginPath();cx.arc(xx,yy,16,0,Math.PI*2);cx.fillStyle='#C7472B';cx.fill();cx.strokeStyle='#fff';cx.lineWidth=3;cx.stroke();cx.fillStyle='#fff';cx.font='bold 17px Arial';cx.textAlign='center';cx.fillText(j+1,xx,yy+6);cx.textAlign='left'})}});cx.fillStyle='#1D2720';cx.font='bold 25px Arial';cx.fillText('OBSERVACIÓN',65,1330);cx.font='21px Arial';let y=1373;y=drawParagraph(cx,'Primera lectura: '+(state.hierarchy.first||'Sin registrar'),65,y,1450,33,2);y=drawParagraph(cx,'Objetivo: '+(state.hierarchy.goal||'Sin registrar'),65,y+10,1450,33,2);y=drawParagraph(cx,'Notas: '+(state.hierarchy.notes||'Sin anotaciones'),65,y+10,1450,33,5);cx.font='17px Arial';cx.fillStyle='#6C766D';cx.fillText('Marcas subjetivas; no es un estudio de seguimiento ocular. · '+new Date().toLocaleDateString('es-AR'),65,1690);out.toBlob(b=>b?dl(b,'lab-oficio-diagnostico-jerarquia.png'):toast('No se pudo crear el PNG'),'image/png')};

