function renderSystem(){const s=state.system,el=$('sPreview');for(const [name,val] of [['--s-bg',safeHex(s.bg,'#FFFFFF')],['--s-ink',safeHex(s.ink,'#161616')],['--s-accent',safeHex(s.accent,'#CA4A2A')],['--s-support',safeHex(s.support,'#dddddd')],['--s-head',JSON.stringify(s.headFont||'Georgia')+', Georgia, serif'],['--s-body',JSON.stringify(s.bodyFont||'Arial')+', Arial, sans-serif'],['--s-gap',clamp(s.space,4,12)+'px'],['--s-radius',clamp(s.radius,0,999)+'px']])el.style.setProperty(name,val);el.dataset.motif=s.motif;el.querySelectorAll('.sys-brand').forEach(n=>n.textContent=s.name||'SIN NOMBRE');el.querySelectorAll('.sys-claim').forEach(n=>n.textContent=s.claim);const ratio=contrast(safeHex(s.bg,'#ffffff'),safeHex(s.ink,'#000000'));$('sContrast').textContent=fmt(ratio)+':1 · '+(ratio>=4.5?'AA normal':ratio>=3?'AA grande':'Contraste bajo');const a=contrast(safeHex(s.bg,'#ffffff'),safeHex(s.accent,'#000000'));$('sAnalysis').textContent=`Contraste tinta/fondo ${fmt(ratio)}:1 (${ratio>=4.5?'apto para texto normal WCAG AA':ratio>=3?'solo apto para texto grande AA':'insuficiente para texto'}). Acento/fondo ${fmt(a)}:1. ${a<3?'No uses el acento para texto pequeño. ':''}Probá las tres piezas: si el sistema solo funciona en el hero, todavía no es un sistema.`}
