$('sFromPair').onclick=()=>{try{const p=JSON.parse(localStorage.getItem('lab-oficio-herramientas-v1')||'{}').pair;if(!p)throw Error();state.system.headFont=(p.customDisplay||p.display||'Georgia').trim();state.system.bodyFont=(p.customBody||p.body||'Arial').trim();$('sHeadFont').value=state.system.headFont;$('sBodyFont').value=state.system.bodyFont;persist();renderSystem();toast('Familias importadas desde herramienta 04')}catch{toast('Primero probá una combinación en Herramientas → Combinaciones')}};
function systemCSS(){const s=state.system;return `/* LAB/OFICIO · Sistema visual de ${String(s.name).replace(/[\n\r*\/]/g,'')} */\n:root {\n  --marca-fondo: ${safeHex(s.bg,'#ffffff')};\n  --marca-tinta: ${safeHex(s.ink,'#000000')};\n  --marca-acento: ${safeHex(s.accent,'#ca4a2a')};\n  --marca-soporte: ${safeHex(s.support,'#eeeeee')};\n  --marca-display: ${JSON.stringify(s.headFont||'Georgia')}, Georgia, serif;\n  --marca-texto: ${JSON.stringify(s.bodyFont||'Arial')}, Arial, sans-serif;\n  --marca-espacio: ${clamp(s.space,4,12)}px;\n  --marca-radio: ${clamp(s.radius,0,999)}px;\n}\n`}
